// Zeigt die aktive Konfiguration im Debug-Fenster (Schlüssel maskiert)
const cfg = JSON.parse(JSON.stringify(global.get('cfg')));
if (cfg.apis.orsKey) cfg.apis.orsKey = cfg.apis.orsKey.slice(0, 4) + '…';
msg.payload = cfg;
return msg;

initialize:
// ============================================================
//  MadridMove – zentrale Konfiguration der Node-RED-Dienste
//  (Collector und Client sind Python-Programme, Einstellungen in python/config.py)
//  Werte lassen sich per Umgebungsvariable überschreiben, z. B. ORS_API_KEY=abc node-red
// ============================================================
const cfg = {
    // Topic-Präfix: wird von configure.py gesetzt, nicht von Hand ändern
    prefix: 'upm-dsiot-g6/move',

    apis: {
        // openrouteservice (Fahrzeit, Höhenmeter; kostenloser Schlüssel, optional)
        ors: env.get('ORS_URL') || 'https://api.openrouteservice.org',
        orsKey: env.get('ORS_API_KEY') || ''
    },

    reco: {
        // Persönliche Grenzen, solange ein Nutzer nichts eingestellt hat ("vorsichtig")
        defaultSettings: { rain: 'kein', windMax: 25, tempMin: 8, tempMax: 30 },
        rainLight: 0.1,          // mm pro 15 min = leichter Regen (Grenze bei "kein Regen")
        rainHeavy: 1.0,          // mm pro 15 min = starker Regen (Grenze bei "leichter Regen ok")

        okBikes: 3,              // ab so vielen Rädern gilt eine Station als sicher
        nearbyStationM: 500,     // Umkreis für Ausweichstationen
        altFasterMin: 5,         // Warnung, wenn zu Fuß/ÖPNV mind. so viel schneller ist
        dockMin: 2,              // Ausleihen + Abstellen
        minPerHmUp: 0.05,        // Aufschlag pro Höhenmeter bergauf (3 s; BiciMAD = E-Bikes)

        windowMin: 30,           // Meldungen nur so viele Minuten vor der Abfahrt
        preInfoMin: 15,          // Vorab-Info so viele Minuten vor der Abfahrt
        staleMin: 15,            // BiciMAD-Daten älter als das = veraltet
        weatherStaleMin: 30,     // Wetterdaten älter als das = veraltet
        maxRoutesPerUser: 3,

        // Streckenprofil ohne ORS (Schätzmodus) und ÖPNV-Schätzung (kein Fahrplan)
        bikeSpeedKmh: 14,
        walkSpeedKmh: 4.8,
        detourFactor: 1.3,       // Luftlinie -> Straßenweg
        transitSpeedKmh: 18,
        transitAccessMin: 8,     // Wege zur und von der Haltestelle
        transitWaitMin: 4        // mittlere Wartezeit
    }
};
global.set('cfg', cfg);
node.status({
    fill: cfg.apis.orsKey ? 'green' : 'yellow', shape: 'dot',
    text: cfg.apis.orsKey ? 'ORS-Schlüssel gesetzt' : 'kein ORS-Schlüssel: Schätzmodus'
});
